import{_ as a,o as t,c as e,a0 as o}from"./chunks/framework.D7EjqxMK.js";const c=JSON.parse('{"title":"AI Pair Programming","description":"","frontmatter":{},"headers":[],"relativePath":"07-ai-coding/01_基础概念/02_AI_Pair_Programming.md","filePath":"07-ai-coding/01_基础概念/02_AI_Pair_Programming.md"}'),i={name:"07-ai-coding/01_基础概念/02_AI_Pair_Programming.md"};function n(d,r,l,h,s,g){return t(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="ai-pair-programming" tabindex="-1">AI Pair Programming <a class="header-anchor" href="#ai-pair-programming" aria-label="Permalink to &quot;AI Pair Programming&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块一 · 01_基础概念 · 第 2 节 <strong>难度</strong>：⭐⭐⭐</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>AI Pair Programming</strong> 将 AI 作为结对编程的伙伴，开发者与 AI 实时协作，AI 提供代码建议、架构建议和调试帮助。</p><hr><h2 id="_2-核心工作模式" tabindex="-1">2. 核心工作模式 <a class="header-anchor" href="#_2-核心工作模式" aria-label="Permalink to &quot;2. 核心工作模式&quot;">​</a></h2><h3 id="模式一-实时补全" tabindex="-1">模式一：实时补全 <a class="header-anchor" href="#模式一-实时补全" aria-label="Permalink to &quot;模式一：实时补全&quot;">​</a></h3><p>在 IDE 中实时提供代码补全建议，开发者按 Tab 接受。</p><h3 id="模式二-对话式编程" tabindex="-1">模式二：对话式编程 <a class="header-anchor" href="#模式二-对话式编程" aria-label="Permalink to &quot;模式二：对话式编程&quot;">​</a></h3><p>通过自然语言对话让 AI 解释代码、生成代码、修复 Bug。</p><h3 id="模式三-代码审查" tabindex="-1">模式三：代码审查 <a class="header-anchor" href="#模式三-代码审查" aria-label="Permalink to &quot;模式三：代码审查&quot;">​</a></h3><p>AI 主动审查代码，提供改进建议。</p><hr><h2 id="_3-ai-结对编程的最佳实践" tabindex="-1">3. AI 结对编程的最佳实践 <a class="header-anchor" href="#_3-ai-结对编程的最佳实践" aria-label="Permalink to &quot;3. AI 结对编程的最佳实践&quot;">​</a></h2><table tabindex="0"><thead><tr><th>实践</th><th>说明</th></tr></thead><tbody><tr><td><strong>始终审查 AI 代码</strong></td><td>AI 可能生成有 Bug 的代码</td></tr><tr><td><strong>分步请求</strong></td><td>大任务拆成小步骤</td></tr><tr><td><strong>提供上下文</strong></td><td>给 AI 完整的文件/函数上下文</td></tr><tr><td><strong>明确约束</strong></td><td>指定技术栈、框架、编码规范</td></tr><tr><td><strong>迭代优化</strong></td><td>通过多轮对话改进代码</td></tr></tbody></table><hr><h2 id="_4-参考资料" tabindex="-1">4. 参考资料 <a class="header-anchor" href="#_4-参考资料" aria-label="Permalink to &quot;4. 参考资料&quot;">​</a></h2><ul><li><a href="https://roamer-tech.com/vscode-github-copilot-pair-programming-workflow-guide-2/" target="_blank" rel="noreferrer">VS Code + GitHub Copilot 结对编程指南 (roamer-tech.com)</a></li><li><a href="https://cloud.tencent.com/developer/article/2622151" target="_blank" rel="noreferrer">Continue — AI 结对编程 (腾讯云)</a></li><li><a href="https://githubdocs.cn/en/copilot/reference/ai-models/supported-models" target="_blank" rel="noreferrer">GitHub Copilot 支持的 AI 模型</a></li></ul>',19)])])}const m=a(i,[["render",n]]);export{c as __pageData,m as default};
